import "fmt"

type IntList []int

func (l IntList) Max() (int, bool) {
	if len(l) == 0 {
		return 0, false
	}
	best := l[0]
	for _, v := range l[1:] {
		if v > best {
			best = v
		}
	}
	return best, true
}

func (l IntList) Contains(x int) bool {
	for _, v := range l {
		if v == x {
			return true
		}
	}
	return false
}

func (l IntList) Filter(keep func(int) bool) IntList {
	var out IntList
	for _, v := range l {
		if keep(v) {
			out = append(out, v)
		}
	}
	return out
}

func main() {
	nums := IntList{5, 12, 7, 20, 3}
	fmt.Println(nums.Max())
	fmt.Println(IntList{}.Max())
	fmt.Println(nums.Contains(7), nums.Contains(8))
	fmt.Println(nums.Filter(func(n int) bool { return n%2 == 0 }))
}

