import "fmt"

type Fraction struct{ Num, Den int }

func gcd(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func (f Fraction) Simplify() Fraction {
	g := gcd(f.Num, f.Den)
	return Fraction{f.Num / g, f.Den / g}
}

func (f Fraction) Add(o Fraction) Fraction {
	return Fraction{f.Num*o.Den + o.Num*f.Den, f.Den * o.Den}.Simplify()
}

func (f Fraction) Mul(o Fraction) Fraction {
	return Fraction{f.Num * o.Num, f.Den * o.Den}.Simplify()
}

func (f Fraction) String() string { return fmt.Sprintf("%d/%d", f.Num, f.Den) }

func main() {
	a := Fraction{1, 2}
	b := Fraction{1, 3}
	fmt.Println(a.Add(b), a.Mul(b), Fraction{6, 8}.Simplify())
}

