func (r Rect) Perimeter() float64 { return 2 * (r.Width + r.Height) }

func apply(rects []Rect, f func(Rect) float64) []float64 {
	result := make([]float64, 0, len(rects))
	for _, r := range rects {
		result = append(result, f(r))
	}
	return result
}

