type Stack []int

func (s *Stack) Push(v int) { *s = append(*s, v) }

func (s *Stack) Pop() (int, bool) {
	if len(*s) == 0 {
		return 0, false
	}
	last := (*s)[len(*s)-1]
	*s = (*s)[:len(*s)-1]
	return last, true
}

func (s *Stack) Len() int { return len(*s) }

func main() {
	var st Stack
	st.Push(1)
	st.Push(2)
	st.Push(3)
	fmt.Println(st.Len())
	for {
		v, ok := st.Pop()
		if !ok {
			break
		}
		fmt.Println(v)
	}
}

