import "fmt"

type Stack[T any] struct {
	items []T
}

func (s *Stack[T]) Push(v T) { s.items = append(s.items, v) }

func (s *Stack[T]) Pop() T {
	last := len(s.items) - 1
	v := s.items[last]
	s.items = s.items[:last]
	return v
}

func main() {
	var s Stack[int]
	s.Push(10)
	s.Push(20)
	// s.Push("oops")
	// Xato: cannot use "oops" (untyped string constant) as int value in argument to s.Push

	n := s.Pop() + 1 // assertion kerak emas
	fmt.Println(n)
}

