import "fmt"

type Expr interface{}

type Num float64
type Var string
type Add struct{ L, R Expr }
type Mul struct{ L, R Expr }

func eval(e Expr, env map[string]float64) (float64, error) {
	switch n := e.(type) {
	case Num:
		return float64(n), nil
	case Var:
		v, ok := env[string(n)]
		if !ok {
			return 0, fmt.Errorf("o'zgaruvchi topilmadi: %s", string(n))
		}
		return v, nil
	case Add:
		l, err := eval(n.L, env)
		if err != nil {
			return 0, err
		}
		r, err := eval(n.R, env)
		return l + r, err
	case Mul:
		l, err := eval(n.L, env)
		if err != nil {
			return 0, err
		}
		r, err := eval(n.R, env)
		return l * r, err
	}
	return 0, fmt.Errorf("noma'lum tugun: %T", e)
}

func main() {
	env := map[string]float64{"x": 3, "y": 4}
	e := Add{Mul{Var("x"), Var("x")}, Var("y")} // x*x + y

	fmt.Println(eval(e, env))
	fmt.Println(eval(Add{Var("z"), Num(1)}, env))
	fmt.Println(eval("matn", env))
}

