		switch r := recover().(type) {
		case nil:
			fmt.Println(name, "-> panic bo'lmadi")
		case error:
			fmt.Println(name, "-> error:", r)
		case string:
			fmt.Println(name, "-> string:", r)
		default:
			fmt.Printf("%s -> boshqa (%T): %v\n", name, r, r)
		}
	}()
	f()
}

func main() {
	zero := 0
	nums := []int{1, 2, 3}

	safely("oddiy", func() {})
	safely("nolga bo'lish", func() { fmt.Println(10 / zero) })
	safely("indeks", func() { fmt.Println(nums[5]) })
	safely("matn", func() { panic("o'zim to'xtatdim") })
	safely("son", func() { panic(404) })
