type memFile struct {
	data   []byte
	pos    int
	closed bool
}

var _ io.ReadWriteCloser = (*memFile)(nil)

// type readOnly struct{}  (faqat Read bor)
// var _ io.ReadWriteCloser = (*readOnly)(nil)
// Xato: *readOnly does not implement io.ReadWriteCloser (missing method Close)

func (m *memFile) Write(p []byte) (int, error) {
	if m.closed {
		return 0, errors.New("fayl yopilgan")
	}
	m.data = append(m.data, p...)
	return len(p), nil
}

func (m *memFile) Read(p []byte) (int, error) {
	if m.pos >= len(m.data) {
		return 0, io.EOF
	}
	n := copy(p, m.data[m.pos:])
	m.pos += n
	return n, nil
}

func (m *memFile) Close() error {
	m.closed = true
	return nil
}

func main() {
	f := &memFile{}
	fmt.Fprintf(f, "salom %d", 1)

	got, _ := io.ReadAll(f)
	fmt.Println(string(got))

