import (
	"container/heap"
	"fmt"
)

type Task struct {
	Name     string
	Priority int
	index    int
}

type PQ []*Task

func (pq PQ) Len() int           { return len(pq) }
func (pq PQ) Less(i, j int) bool { return pq[i].Priority > pq[j].Priority } // kattasi oldin
func (pq PQ) Swap(i, j int) {
	pq[i], pq[j] = pq[j], pq[i]
	pq[i].index = i
	pq[j].index = j
}
func (pq *PQ) Push(x any) {
	t := x.(*Task)
	t.index = len(*pq)
	*pq = append(*pq, t)
}
func (pq *PQ) Pop() any {
	old := *pq
	t := old[len(old)-1]
	*pq = old[:len(old)-1]
	return t
}

func main() {
	pq := &PQ{}
	report := &Task{Name: "hisobot", Priority: 2}
	heap.Push(pq, &Task{Name: "xat", Priority: 1})
	heap.Push(pq, report)
	heap.Push(pq, &Task{Name: "ta'mirlash", Priority: 3})

	report.Priority = 10 // hisobot shoshilinch bo'ldi
	heap.Fix(pq, report.index)

	for pq.Len() > 0 {
		t := heap.Pop(pq).(*Task)
		fmt.Println(t.Priority, t.Name)
	}
}

