type Money int // tiyin

func (m *Money) UnmarshalJSON(b []byte) error {
	var s string
	if err := json.Unmarshal(b, &s); err != nil {
		return err
	}
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return fmt.Errorf("pul formati noto'g'ri: %w", err)
	}
	*m = Money(math.Round(f * 100))
	return nil
}

func main() {
	var p struct{ Price Money }

	err := json.Unmarshal([]byte(`{"Price":"125.50"}`), &p)
	fmt.Println(int(p.Price), err)

