	for _, url := range []string{"/?name=Aziz", "/"} {
		rec := httptest.NewRecorder()
		Greeter{"Salom"}.ServeHTTP(rec, httptest.NewRequest("GET", url, nil))
		fmt.Println(rec.Code, rec.Body.String())
	}
}

